INSERT INTO [${dbxschemaname}].[communicationtemplate] ([Id], [LanguageCode], [AlertSubTypeId], [ChannelID], [Status_id], [Name], [Text], [Subject]) VALUES ('602', 'en-US', 'APPROVE_DOMESTIC_WIRE_TRANSFER', 'CH_NOTIFICATION_CENTER', 'SID_EVENT_SUCCESS', 'Approve Domestic Wire Transfer request', 'Your Request for Approval towards Wire Transfer of [#]amount[/#] dated [#]Senddate[/#] from Account [#]MaskedFromAccount[/#] to payee [#]MaskedPayeeName[/#] with Reference ID [#]transactionID[/#] has been Approved by [#]ActedUserName[/#] . Please log on to Internet Banking to view the details.', 'Domestic Wire Transfer request Approved');
INSERT INTO [${dbxschemaname}].[communicationtemplate] ([Id], [LanguageCode], [AlertSubTypeId], [ChannelID], [Status_id], [Name], [Text], [Subject]) VALUES ('603', 'en-US', 'APPROVE_DOMESTIC_WIRE_TRANSFER', 'CH_EMAIL', 'SID_EVENT_SUCCESS', 'Approve Domestic Wire Transfer request', 'Dear [#]FirstName[/#] [#]LastName[/#] ,<br>Your Request for Approval towards Wire Transfer of [#]amount[/#] dated [#]Senddate[/#] from Account [#]MaskedFromAccount[/#] to payee [#]MaskedPayeeName[/#] with Reference ID [#]transactionID[/#] has been Approved by [#]ActedUserName[/#] . Please log on to Internet Banking to view the details.<br>Regards,<br>Temenos Digital Bank', 'Domestic Wire Transfer request Approved');
INSERT INTO [${dbxschemaname}].[communicationtemplate] ([Id], [LanguageCode], [AlertSubTypeId], [ChannelID], [Status_id], [Name], [Text], [Subject]) VALUES ('604', 'en-US', 'APPROVE_DOMESTIC_WIRE_TRANSFER_INITIATOR', 'CH_SMS', 'SID_EVENT_SUCCESS', 'Approve Domestic Wire Transfer request', 'Your Request for Approval towards Wire Transfer of [#]amount[/#] dated [#]Senddate[/#] from Account [#]MaskedFromAccount[/#] to payee [#]MaskedPayeeName[/#] with Reference ID [#]transactionID[/#] has been Approved by [#]ActedUserName[/#] and is now considered authorized . Please log on to Internet Banking to view the details.', 'Domestic Wire Transfer request Approved');
